class _BundleImporter(_abc.MetaPathFinder, _abc.Loader):
    def find_spec(self, name, path=None, target=None):
        if name == _PKG:
            return _util.spec_from_loader(name, self, is_package=True)
        if name.startswith(_PKG + ".") and name[len(_PKG) + 1:] in _SOURCES:
            return _util.spec_from_loader(name, self)
        if name == _PKG + "._embedded":
            return _util.spec_from_loader(name, self)
        return None

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__name__
        if name == _PKG:
            module.__path__ = []
            return
        sub = name[len(_PKG) + 1:]
        if sub == "_embedded":
            module.DATA = _DATA
            return
        code = _zlib.decompress(_b64.b64decode(_SOURCES[sub])).decode("utf-8")
        exec(compile(code, "<" + _PKG + "/" + sub + ".py>", "exec"), module.__dict__)


if not any(getattr(f, "_pkg", None) == _PKG for f in _sys.meta_path):
    _finder = _BundleImporter()
    _finder._pkg = _PKG
    _sys.meta_path.insert(0, _finder)

